import{_ as i,l,o as e,c as n,v as t,p as s,x as o,d,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"零知识直觉","description":"","frontmatter":{"title":"零知识直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/zero-knowledge-intuition.md","filePath":"cs/zero-knowledge-intuition.md","lastUpdated":1789023840000}'),p={name:"cs/zero-knowledge-intuition.md"};function E(A,a,u,_,f,m){const r=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="零知识直觉" tabindex="-1">零知识直觉 <a class="header-anchor" href="#零知识直觉" aria-label="Permalink to &quot;零知识直觉&quot;">​</a></h1><div class="epigraph"><p>证明者让验证者相信命题成立，而不多给能转述给第三人的证据。模拟器能在不知道证人时伪造与真实不可区分的对话——这就是「零知识」。</p><footer>—— Goldwasser, Micali and Rackoff, The Knowledge Complexity of Interactive Proof Systems, 1985, 1989</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/post-quantum-kyber">后量子</a>换了陷门。缺口是<strong>另一类协议目标</strong>：不传输证人，只传输可验的对话。主干没有 ZK 课；本课直觉，不写电路到多项式的全套。与<a href="/cs/interactive-proofs">交互证明</a>的复杂度课只点名，不重推 IP=PSPACE。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>签名证明「持有私钥的人认过消息」，但签名本身可转述。ZK：验证者自己能模拟视图，故不能拿对话去说服别人（在适当模型下）。缺口是完备性、可靠性、零知识三条，不是具体 zk-SNARK 产品。</p><h3 id="可靠性-零知识" tabindex="-1">可靠性≠零知识 <a class="header-anchor" href="#可靠性-零知识" aria-label="Permalink to &quot;可靠性≠零知识&quot;">​</a></h3><p>可靠性：假命题不能过。零知识：真命题的对话不泄漏证人。可以强可靠而完全不零知识（直接给证人）。</p><p><span class="marginnote">GMR 1985/1989。Schnorr 协议是离散对数的经典 Σ 协议形状，本课只当例子点名，不给用于伪造的代数步骤。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用「洞穴/口令」隐喻后立刻升到游戏：模拟器、提取器。指出非交互需要 Fiat–Shamir 与随机预言机假设。后课承诺是 Σ 协议的零件。</p>',12)),(e(),s(c,null,{default:o(()=>[h(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E8%AF%81%E4%BA%BA%22%5D%20--%3E%20P%5B%22%E8%AF%81%E6%98%8E%E8%80%85%22%5D%0A%20%20P%20--%3E%20V%5B%22%E9%AA%8C%E8%AF%81%E8%80%85%E5%8F%AA%E4%BF%A1%E5%91%BD%E9%A2%98%22%5D%0A%20%20S%5B%22%E6%A8%A1%E6%8B%9F%E5%99%A8%E6%97%A0%E8%AF%81%E4%BA%BA%22%5D%20--%3E%20VIEW%5B%22%E8%A7%86%E5%9B%BE%E4%B8%8D%E5%8F%AF%E5%8C%BA%E5%88%86%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>ZK 服务「选择性披露」：我属于集合、我付过款、我知道原像——验证者不带走可转述的证书。它不替代 TLS，不替代 AEAD。计算成本高，协议要选陈述。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Groth16 的配对细节，不把区块链当必经应用。下一课承诺与 Merkle 树：隐藏后可打开，以及把集合收成根。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>KEM 换困难问题；ZK 换「证明而不给证人」。</li><li>完备、可靠、零知识三条分开。</li><li>模拟器测试零知识；转述性与签名不同。</li><li>下一课：承诺与 Merkle 树。</li><li>出处：Goldwasser, Micali and Rackoff, 1985/1989；对照 Goldreich。</li></ul>',8))])}const B=i(p,[["render",E]]);export{P as __pageData,B as default};
